#!/usr/bin/env node
"use strict";
const fs = require("node:fs");
const os = require("node:os");
const path = require("node:path");
const zlib = require("node:zlib");
const child = require("node:child_process");

const packageRoot = path.resolve(__dirname, "..", "..");
const work = fs.mkdtempSync(path.join(os.tmpdir(), "evolutionary-city-s03-"));
const dataDir = path.join(work, "data");
const outputDir = path.join(work, "visual-assets");
const scriptDir = path.join(work, "repro");
fs.mkdirSync(dataDir, { recursive: true });
fs.mkdirSync(outputDir, { recursive: true });
fs.mkdirSync(scriptDir, { recursive: true });

const scripts = {"fetch_s03_osm.py": "", "build_story_data.py": "", "test_story_data.py": ""};
for (const [name, encoded] of Object.entries(scripts)) {
  fs.writeFileSync(path.join(scriptDir, name), Buffer.from(encoded, "base64"));
}
fs.writeFileSync(path.join(dataDir, "osm-s03-20260820.osm"), zlib.gunzipSync(Buffer.from("", "base64")));
fs.writeFileSync(path.join(dataDir, "osm-s03-20260820.meta.json"), Buffer.from("", "base64"));

const env = { ...process.env, ECS_ROOT: packageRoot, ECS_DATA_DIR: dataDir, ECS_VISUAL_ASSETS: outputDir };
for (const name of ["build_story_data.py", "test_story_data.py"]) {
  const result = child.spawnSync("python", [path.join(scriptDir, name)], { env, encoding: "utf8", stdio: "pipe" });
  process.stdout.write(result.stdout || "");
  process.stderr.write(result.stderr || "");
  if (result.status !== 0) process.exit(result.status || 1);
}
console.log(`Reproduced S03 story data in ${outputDir}`);
console.log("Inputs: frozen OSM snapshot + fixed seed 20260820. No remote request was made.");
